import {
  copyFile,
  mkdir,
  open,
  readDir,
  readFile,
  readTextFile,
  remove,
  rename,
  stat,
  watch,
  writeTextFile,
} from '@tauri-apps/plugin-fs';

import { hasRelevantWatchPath } from './watch-filter';

/** 取消监听的函数 (`plugin-fs` 的 `UnwatchFn`; 用 ReturnType 取, 免得依赖它的类型名)。 */
export type Unwatch = Awaited<ReturnType<typeof watch>>;

export interface FsEntry {
  name: string;
  isDirectory: boolean;
}

export interface FsStat {
  type: 'file' | 'directory' | 'symbolicLink' | 'unknown';
  size: number;
  mtime?: number;
  ctime?: number;
}

export interface ExistsResult {
  exists: boolean;
  isDirectory: boolean;
}

export const fs = {
  async stat(path: string): Promise<FsStat | null> {
    try {
      const info = await stat(path);
      return {
        type: info.isDirectory ? 'directory' : 'file',
        size: info.size ?? 0,
      };
    } catch {
      return null;
    }
  },

  async exists(path: string): Promise<ExistsResult> {
    try {
      const info = await stat(path);
      return { exists: true, isDirectory: info.isDirectory };
    } catch {
      return { exists: false, isDirectory: false };
    }
  },

  async readDir(path: string): Promise<FsEntry[]> {
    const entries = await readDir(path);
    return entries.map((e) => ({ name: e.name, isDirectory: e.isDirectory }));
  },

  async readText(path: string): Promise<string> {
    return readTextFile(path);
  },

  /** 容错文本读取: 以字节读取并用非致命 UTF-8 解码, 含非法字节的文件 (如部分 JSON/模型文件) 也不会抛错。 */
  async readTextLossy(path: string): Promise<string> {
    const bytes = await readFile(path);
    return new TextDecoder('utf-8', { fatal: false }).decode(bytes);
  },

  async readBytes(path: string): Promise<Uint8Array> {
    return readFile(path);
  },

  /** 只读取文件头部若干字节 (用于类型探测, 避免大文件整体读入内存)。 */
  async readHead(path: string, length: number): Promise<Uint8Array> {
    const handle = await open(path);
    try {
      const buf = new Uint8Array(length);
      await handle.read(buf);
      return buf;
    } finally {
      await handle.close();
    }
  },

  async writeText(path: string, content: string): Promise<void> {
    await writeTextFile(path, content);
  },

  async mkdir(path: string): Promise<void> {
    await mkdir(path, { recursive: true });
  },

  async remove(path: string, recursive = false): Promise<void> {
    await remove(path, { recursive });
  },

  async rename(from: string, to: string): Promise<void> {
    await rename(from, to);
  },

  async copyFile(from: string, to: string): Promise<void> {
    await copyFile(from, to);
  },

  /**
   * 监听一个目录的变化, 变化时回调。
   *
   * `recursive` **默认 false, 只有展平模式才该传 true**: 展平视图要显示子目录里的文件, 分层
   * 视图只看当前这一层。在大目录上递归注册监听代价很高 —— `notify` 要为每个子目录建句柄,
   * 此后项目里任何活动都会触发重列目录并重建带缩略图的行, 整个应用变迟钝。
   *
   * `.git/` 一类版本控制元数据由 `lib/watch-filter.ts` 跳过, 否则 `git status` 自己写的索引锁
   * 会把这个监听一起叫醒; `debounceMs` 交给插件自己做 (它内置了防抖队列), 外面再包一层定时器
   * 只会把延迟叠成两倍。
   */
  async watchDirectory(path: string, onChange: () => void, debounceMs = 160, recursive = false): Promise<Unwatch> {
    return watch(
      path,
      (event) => {
        if (!hasRelevantWatchPath(event.paths)) return;
        onChange();
      },
      { recursive, delayMs: debounceMs }
    );
  },
};
